INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.93.1',
  '2026-09-20',
  'Пульт ТВ: выбор экрана, когда плеер открыт в двух местах',
  E'Если медиатека открыта сразу в нескольких местах — на телевизоре и, скажем, на компьютере, — пульт теперь их различает. Сверху появляется выбор: «Приложение на ТВ» или «Браузер компьютера». Команды, перемотка и картинка с телефона уходят только выбранному экрану, и показывается тоже он.\n\nРаньше оба плеера были для пульта одним целым: пауза с пульта останавливала видео на телевизоре, даже если код набрали с экрана компьютера, а название фильма в пульте мелькало, показывая то один, то другой. На экране рядом с кодом теперь видно, какой это экран.\n\nЭто про несколько окон одной медиатеки. Несколько разных приставок (у каждой свой домашний компьютер с агентом) и раньше подключались отдельно и в списке приставок остаются как были.',
  E'Комната шины — это агент, а не плеер: две открытые страницы одного агента входили в одну комнату с одним кодом, Broadcast слал команды обеим, и обе отвечали state — отсюда мельтешение в пульте и пауза «не того» видео.\n\ntvrelay: у клиента появился id (счётчик хаба, «s1», «s2») и имя; Hub.SendTo(key, id, data) — адресная доставка одному плееру, Hub.Screens(key) — список экранов комнаты. httpapi/tv.go: при входе плеер получает {t:"screen", id}; presence несёт screens; шина читает в сообщении только «t», «to» и «name» (остальное по-прежнему непрозрачно): {t:"iam", name} задаёт имя экрана, сообщение пульта с «to» уходит одному плееру, без «to» — всем, как раньше. /tv/cast и /tv/cast/stop принимают screen=; несуществующий экран — 409 и временный файл удаляется.\n\nСтраница плеера: свой номер экрана из {t:"screen"}, в каждом ответе поле «s», имя экрана («Приложение на ТВ», «Браузер приставки», «Браузер компьютера») и подпись рядом с кодом, когда экранов больше одного. Пульт (RemoteView.vue): список экранов из presence, выбор кнопками при двух и более, ответы чужих экранов отбрасываются по «s», команды уходят с «to», при исчезновении выбранного экрана — переход на первый оставшийся.\n\nПроверено: relay_test.go (номера, список, уход экрана, отправка в никуда), локальный прод с двумя сырыми веб-сокетами приставок и пультом (адресная команда, подписанные состояния, картинка только выбранному, 409 на ушедший экран), два окна плеера в браузере против локального прода — «во весь экран» с пульта применилось только ко второму окну.'
);
-- +goose StatementEnd

